char *read_all(const char *path, size_t *len) {
  FILE *fp = fopen(path, "rb");
  if (fp == NULL) return NULL;
  char *buf = malloc(4096 + 1);
  if (buf == NULL) { fclose(fp); return NULL; }
  size_t n = fread(buf, 1, 4096, fp);
  if (ferror(fp)) { free(buf); fclose(fp); return NULL; }
  fclose(fp);
  buf[n] = '\0';
  *len = n;
  return buf;
}
